function initSearchType() {
var savedData = {};
try {
savedData = JSON.parse(source.getVariable() || "{}");
} catch (e) {
savedData = {};
}   
if (typeof savedData.searchType === 'undefined') {
savedData.searchType = 1;
}   
source.setVariable(JSON.stringify(savedData));
return savedData.searchType;
}

function setSearchType(type) {
var savedData = {};
try {
savedData = JSON.parse(source.getVariable() || "{}");
} catch (e) {
savedData = {};
}   
savedData.searchType = type;
source.setVariable(JSON.stringify(savedData));  
var typeName;
if (type === 1) {
typeName = "小说";
} else if (type === 2) {
typeName = "套图";
} else if (type === 3) {
typeName = "漫画";
} else if (type === 4) {
typeName = "视频";
}
java.toast("\n✅ 已切换到: 【" + typeName + "】");
}

function showSearchType() {
var currentType = initSearchType();
var typeName;   
if (currentType === 1) {
typeName = "小说";
} else if (currentType === 2) {
typeName = "套图";
} else {
typeName = "漫画";
}   
java.longToast("\n🔍 当前搜索类型: 【" + typeName + "】");
}
initSearchType();

