@js:
let model = (title,url,num)=>{
    return {title:title,url:url,style:{layout_flexGroup:1,layout_flexBasisPercent:num}}
}

let ajax = java.ajax("http://comic.321mh.com/v1/comic/getcomicsortandroid?platformname=android&productname=mht")
let url="https://getconfig-globalapi.yyhao.com/app_api/v5/getsortlist/?page={{page}}&orderby=date&search_type=&comic_sort=tihuan&search_key=&platformname=android&productname=mht"

丁斐=JSON.parse(ajax).data.map(i=>{
	t=url.replace("tihuan",i.urlid)
	return  model(i.name,t,0.15)
	})


JSON.stringify(丁斐)

