var next = matchResult ? matchResult[1] : "";
var url = next ? eval(next) : "";
java.log(url);

if (url) {
    var nextChapterElement = document.select("*:contains(下一章), *:contains(最后一章了)").first();

    if (nextChapterElement) {
        java.log("找到下一章或最后一章了，停止执行。");
    } else {
        eval(url.replace(/var/, ""));
    }
}

